import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"14、【大有】 乾下离上","description":"横渠易说 - 14、【大有】 乾下离上","frontmatter":{"title":"14、【大有】 乾下离上","description":"横渠易说 - 14、【大有】 乾下离上"},"headers":[],"relativePath":"zh/classics/hengqu/016.md","filePath":"zh/classics/hengqu/016.md"}'),l={name:"zh/classics/hengqu/016.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_14、【大有】-乾下离上" tabindex="-1">14、【大有】 乾下离上 <a class="header-anchor" href="#_14、【大有】-乾下离上" aria-label="Permalink to “14、【大有】 乾下离上”">​</a></h1><h3 id="彖曰-大有-柔得尊位-大中而上下应之曰大有。其德刚健而文明-应乎天而时行-是以元亨。" tabindex="-1">彖曰：大有，柔得尊位，大中而上下应之曰大有。其德刚健而文明，应乎天而时行，是以元亨。 <a class="header-anchor" href="#彖曰-大有-柔得尊位-大中而上下应之曰大有。其德刚健而文明-应乎天而时行-是以元亨。" aria-label="Permalink to “彖曰：大有，柔得尊位，大中而上下应之曰大有。其德刚健而文明，应乎天而时行，是以元亨。”">​</a></h3><p>柔得盛位，非所固有，故曰大有。 刚健故应乎天，文明故时行。</p><h3 id="象曰-火在天上-大有-君子以遏恶扬善-顺天休命。" tabindex="-1">象曰：火在天上，大有，君子以遏恶扬善，顺天休命。 <a class="header-anchor" href="#象曰-火在天上-大有-君子以遏恶扬善-顺天休命。" aria-label="Permalink to “象曰：火在天上，大有，君子以遏恶扬善，顺天休命。”">​</a></h3><p>柔能大有，非天道也，乃天命也，故曰“顺天休命”。遏恶扬善，勉□也。</p><h3 id="初九-无交害-匪咎。艰则无咎。-象曰-大有初九-无交害也。" tabindex="-1">初九，无交害，匪咎。艰则无咎。 象曰：大有初九，无交害也。 <a class="header-anchor" href="#初九-无交害-匪咎。艰则无咎。-象曰-大有初九-无交害也。" aria-label="Permalink to “初九，无交害，匪咎。艰则无咎。 象曰：大有初九，无交害也。”">​</a></h3><p>二应于五，三能自通，四匪其旁，惟初无交故有害，然非其咎</p><h3 id="九二-大车以载-有攸往-无咎。-象曰-大车以载-积中不败也。" tabindex="-1">九二，大车以载，有攸往，无咎。 象曰：“大车以载”，积中不败也。 <a class="header-anchor" href="#九二-大车以载-有攸往-无咎。-象曰-大车以载-积中不败也。" aria-label="Permalink to “九二，大车以载，有攸往，无咎。 象曰：“大车以载”，积中不败也。”">​</a></h3><h3 id="九三-公用亨于天子-小人弗克。-象曰-公用亨于天子-小人害也。" tabindex="-1">九三，公用亨于天子，小人弗克。 象曰：“公用亨于天子”，小人害也。 <a class="header-anchor" href="#九三-公用亨于天子-小人弗克。-象曰-公用亨于天子-小人害也。" aria-label="Permalink to “九三，公用亨于天子，小人弗克。 象曰：“公用亨于天子”，小人害也。”">​</a></h3><p>非柔中文明之主不能察，非刚健不私之臣不能通，故曰“小人弗克”。</p><h3 id="九四-匪其彭-无咎。-象曰-匪其彭无咎-明辨晢也。" tabindex="-1">九四，匪其彭，无咎。 象曰：“匪其彭无咎”，明辨晢也。 <a class="header-anchor" href="#九四-匪其彭-无咎。-象曰-匪其彭无咎-明辨晢也。" aria-label="Permalink to “九四，匪其彭，无咎。 象曰：“匪其彭无咎”，明辨晢也。”">​</a></h3><h3 id="六五-厥孚交如威如-吉。-象曰-厥孚交如-信以发志也-威如之吉-易而无备也。" tabindex="-1">六五，厥孚交如威如，吉。 象曰：“厥孚交如”，信以发志也；威如之吉，易而无备也。 <a class="header-anchor" href="#六五-厥孚交如威如-吉。-象曰-厥孚交如-信以发志也-威如之吉-易而无备也。" aria-label="Permalink to “六五，厥孚交如威如，吉。 象曰：“厥孚交如”，信以发志也；威如之吉，易而无备也。”">​</a></h3><p>人威重有德望，则人自畏服，易曰“厥孚交如威如吉”，君子以至诚交人，然后有威重。“威如之吉，易而无备也”，君子至平易，有何关防拟备？惟以抑抑威仪为德之隅，俨然人望而畏之，既易而无备，则威如乃吉也。</p><h3 id="上九-自天祐之-吉无不利。-象曰-大有上吉-自天祐也。" tabindex="-1">上九，自天祐之，吉无不利。 象曰：大有上吉，自天祐也。 <a class="header-anchor" href="#上九-自天祐之-吉无不利。-象曰-大有上吉-自天祐也。" aria-label="Permalink to “上九，自天祐之，吉无不利。 象曰：大有上吉，自天祐也。”">​</a></h3><p>以刚而下柔，居上而志应于中，故曰履信思顺，又以尚贤，盖五阳一阴，又无物以间焉耳。刚柔相求，情也，信也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
